/*
 * A071025  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 124".
 * https://oeis.org/A071025
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   not stated
 * Range:     u8 n <= 98, u16 n <= 98, u32 n <= 98, u64 n <= 98, u128 n <= 98,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A071025: Triangle of Rule 124
 * The entry a(n) is the nth element of the triangle read row‑by‑row
 * starting with row 0 = [1].  Row r (0‑based) has length r+1 and is
 * produced from row r‑1 by applying Rule 124 to each neighbourhood
 * (padding with zeros outside the boundaries).  This implementation
 * generates rows incrementally, stores all cells in a flat array and
 * memoises the result for arbitrary access. */

#include <stdlib.h>
#include <stdint.h>

static const uint8_t rule124[8] =
    {0, 0, 1, 1, 1, 1, 1, 0};

static idx_t  *row_start  = NULL;   /* start index of each row in cells array   */
static size_t  row_cap    = 0;      /* allocated capacity for row_start          */
static idx_t  max_row      = (idx_t)-1;   /* highest row that has been computed      */

static uint8_t *cells      = NULL;   /* flat storage of all rows                */
static size_t   cells_cap  = 0;      /* capacity of cells array                 */
static idx_t    cells_next = 0;      /* next free position in cells             */

/* Find the row that contains the linear index n.
 * r is the largest integer with r*(r+1)/2 <= n. */
static idx_t
row_of(idx_t n)
{
    idx_t low  = 0;
    idx_t high = 1;
    while ((idx_t)((__int128)high * (high + 1) / 2) <= n) {
        high <<= 1;
    }
    while (low < high) {
        idx_t mid = low + (high - low + 1) / 2;
        if ((idx_t)((__int128)mid * (mid + 1) / 2) <= n) {
            low = mid;
        } else {
            high = mid - 1;
        }
    }
    return low;
}

/* Ensure that all rows up to r (inclusive) have been generated. */
static void
ensure_rows(idx_t r)
{
    /* First use: initialise data structures. */
    if (row_start == NULL) {
        row_cap = 4;
        row_start = (idx_t *)calloc(row_cap, sizeof(idx_t));
        cells_cap = 8;
        cells     = (uint8_t *)calloc(cells_cap, sizeof(uint8_t));

        /* Row 0 */
        row_start[0] = 0;
        cells[0]     = 1;
        cells_next   = 1;
        max_row      = 0;
        row_start[1] = cells_next;   /* end of row 0 */
    }

    if (max_row != (idx_t)-1 && r <= max_row) return;

    /* Grow row_start array if needed. */
    if (row_cap <= r + 1) {
        size_t new_cap = row_cap ? row_cap * 2 : 4;
        while (new_cap <= r + 1) new_cap <<= 1;
        row_start = (idx_t *)realloc(row_start, new_cap * sizeof(idx_t));
        row_cap   = new_cap;
    }

    /* Generate missing rows. */
    for (idx_t nr = max_row + 1; nr <= r; ++nr) {
        idx_t prev_len   = nr;                 /* length of row nr‑1 */
        idx_t prev_start = row_start[nr - 1];   /* start index of row nr‑1 */
        idx_t curr_len   = nr + 1;             /* length of row nr   */
        idx_t curr_start = cells_next;         /* start index of row nr */

        /* Reserve space for the new row. */
        if (cells_next + curr_len > cells_cap) {
            size_t new_cap = cells_cap ? cells_cap * 2 : 8;
            while (new_cap < cells_next + curr_len) new_cap <<= 1;
            cells = (uint8_t *)realloc(cells, new_cap * sizeof(uint8_t));
            cells_cap = new_cap;
        }

        /* Compute each cell of the new row by Rule 124. */
        for (idx_t c = 0; c < curr_len; ++c) {
            uint8_t left   = (c > 0)           ? cells[prev_start + c - 1] : 0;
            uint8_t center = (c < prev_len)    ? cells[prev_start + c]     : 0;
            uint8_t right  = (c + 1 < prev_len) ? cells[prev_start + c + 1] : 0;
            uint8_t pattern = (left << 2) | (center << 1) | right;
            cells[curr_start + c] = rule124[pattern];
        }

        cells_next += curr_len;
        row_start[nr]     = curr_start;
        row_start[nr + 1] = cells_next;
    }

    max_row = r;
}

seq_t
a(idx_t n)
{
    idx_t r = row_of(n);           /* row containing n */
    ensure_rows(r);                /* generate rows up to r */
    return (seq_t)cells[n];        /* nth entry in the flat array */
}
